	private int db_versionStmtSize = 0;

	private int db_versionInserted = 0;

	private List<Db_version> db_versions = 
		new LinkedList<Db_version>();

	private PreparedStatement db_versionStmt = null;

	public static class Db_version {
		protected String version_number; 
	}
	
	protected void insertDb_version( List<Db_version> db_versions )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = db_versions.size();
		if ( db_versionStmtSize != size ) {
			if ( db_versionStmt != null ) {
				db_versionStmt.close();
			}
			String values = "(?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			db_versionStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO db_version (version_number)"  
				+" VALUES " + valuesList.toString()  );
			
			db_versionStmtSize = size;
		}

		int offset = 1;
			
		for (Db_version db_version : db_versions) {
			if ( db_version.version_number == null )
				db_versionStmt.setNull(offset++, 12);
			else
				db_versionStmt.setString(offset++, db_version.version_number);
		}
		db_versionStmt.executeUpdate();
		db_versionInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Db_versions in {} milliseconds.", size, db_versionInserted, elapsed );		
	}
		
	
	private void flushDb_version(  )
	throws SQLException {
		if ( ! db_versions.isEmpty() )
			insertDb_version(db_versions);
		if ( db_versionStmt != null )
			db_versionStmt.close();
	}	

	/**
	 * Db_version
	 * @param version_number Numero de Version de la Base de Datos
	 * @throws SQLException
	*/
	protected void insertDb_version(String version_number)
	throws SQLException {

		Db_version db_version_ = new Db_version();
		db_version_.version_number = version_number;

		db_versions.add(db_version_);
		
		int db_versionCount = db_versions.size();
		
		if ( 10 * db_versionCount >=  this.maxAllowedPacket ){
			insertDb_version(db_versions);
			db_versions.clear();
		} 
	}



	private int pcategoryStmtSize = 0;

	private int pcategoryInserted = 0;

	private List<Pcategory> pcategorys = 
		new LinkedList<Pcategory>();

	private PreparedStatement pcategoryStmt = null;

	public static class Pcategory {
		protected Integer id; 
		protected Integer domain; 
		protected String name; 
		protected String detail_pattern; 
		protected Integer pcategory_group; 
	}
	
	protected void insertPcategory( List<Pcategory> pcategorys )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = pcategorys.size();
		if ( pcategoryStmtSize != size ) {
			if ( pcategoryStmt != null ) {
				pcategoryStmt.close();
			}
			String values = "(?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			pcategoryStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO pcategory (id,domain,name,detail_pattern,pcategory_group)"  
				+" VALUES " + valuesList.toString()  );
			
			pcategoryStmtSize = size;
		}

		int offset = 1;
			
		for (Pcategory pcategory : pcategorys) {
			if ( pcategory.id == null )
				pcategoryStmt.setNull(offset++, 4);
			else
				pcategoryStmt.setInt(offset++, pcategory.id);
			if ( pcategory.domain == null )
				pcategoryStmt.setNull(offset++, 4);
			else
				pcategoryStmt.setInt(offset++, pcategory.domain);
			if ( pcategory.name == null )
				pcategoryStmt.setNull(offset++, 12);
			else
				pcategoryStmt.setString(offset++, pcategory.name);
			if ( pcategory.detail_pattern == null )
				pcategoryStmt.setNull(offset++, 12);
			else
				pcategoryStmt.setString(offset++, pcategory.detail_pattern);
			if ( pcategory.pcategory_group == null )
				pcategoryStmt.setNull(offset++, 4);
			else
				pcategoryStmt.setInt(offset++, pcategory.pcategory_group);
		}
		pcategoryStmt.executeUpdate();
		pcategoryInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Pcategorys in {} milliseconds.", size, pcategoryInserted, elapsed );		
	}
		
		private int pcategoryId = -1;
		
		private void initPcategoryId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `pcategory`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.pcategoryId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextPcategoryId() {
			return ++this.pcategoryId;
		} 

		public void setPcategoryId(Integer pcategoryId) {
			this.pcategoryId = pcategoryId;
		} 
	
	private void flushPcategory(  )
	throws SQLException {
		if ( ! pcategorys.isEmpty() )
			insertPcategory(pcategorys);
		if ( pcategoryStmt != null )
			pcategoryStmt.close();
	}	

