	private int commissionStmtSize = 0;

	private int commissionInserted = 0;

	private List<Commission> commissions = 
		new LinkedList<Commission>();

	private PreparedStatement commissionStmt = null;

	public static class Commission {
		protected Integer id; 
		protected Integer domain; 
		protected String name; 
		protected Date start_date; 
		protected Date end_date; 
	}
	
	protected void insertCommission( List<Commission> commissions )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = commissions.size();
		if ( commissionStmtSize != size ) {
			if ( commissionStmt != null ) {
				commissionStmt.close();
			}
			String values = "(?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			commissionStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO commission (id,domain,name,start_date,end_date)"  
				+" VALUES " + valuesList.toString()  );
			
			commissionStmtSize = size;
		}

		int offset = 1;
			
		for (Commission commission : commissions) {
			if ( commission.id == null )
				commissionStmt.setNull(offset++, 4);
			else
				commissionStmt.setInt(offset++, commission.id);
			if ( commission.domain == null )
				commissionStmt.setNull(offset++, 4);
			else
				commissionStmt.setInt(offset++, commission.domain);
			if ( commission.name == null )
				commissionStmt.setNull(offset++, 12);
			else
				commissionStmt.setString(offset++, commission.name);
			if ( commission.start_date == null )
				commissionStmt.setNull(offset++, 91);
			else
				commissionStmt.setDate(offset++, commission.start_date);
			if ( commission.end_date == null )
				commissionStmt.setNull(offset++, 91);
			else
				commissionStmt.setDate(offset++, commission.end_date);
		}
		commissionStmt.executeUpdate();
		commissionInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Commissions in {} milliseconds.", size, commissionInserted, elapsed );		
	}
		
		private int commissionId = -1;
		
		private void initCommissionId() 
		throws SQLException  {
			ResultSet rs = null;
			Statement stmt = null;
			try {
				stmt = mysqlConnection.createStatement();
				rs = stmt.executeQuery("SELECT max(id) FROM `commission`" );
				Integer max = null;
				if ( rs.next() ) {		
					max = rs.getInt(1);
				}
				this.commissionId = max == null ? 0 : max;
			}
			finally {
				if ( rs != null )
					rs.close(); 
				if ( stmt != null )
					stmt.close(); 
			}
		}

		public int nextCommissionId() {
			return ++this.commissionId;
		} 

		public void setCommissionId(Integer commissionId) {
			this.commissionId = commissionId;
		} 
	
	private void flushCommission(  )
	throws SQLException {
		if ( ! commissions.isEmpty() )
			insertCommission(commissions);
		if ( commissionStmt != null )
			commissionStmt.close();
	}	

