	protected void insertInventory( List<Inventory> inventorys )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = inventorys.size();
		if ( inventoryStmtSize != size ) {
			if ( inventoryStmt != null ) {
				inventoryStmt.close();
			}
			String values = "(?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			inventoryStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO inventory (id,domain,inventory_date,warehouse,description)"  
				+" VALUES " + valuesList.toString()  );
			
			inventoryStmtSize = size;
		}

		int offset = 1;
			
		for (Inventory inventory : inventorys) {
			if ( inventory.id == null )
				inventoryStmt.setNull(offset++, 4);
			else
				inventoryStmt.setInt(offset++, inventory.id);
			if ( inventory.domain == null )
				inventoryStmt.setNull(offset++, 4);
			else
				inventoryStmt.setInt(offset++, inventory.domain);
			if ( inventory.inventory_date == null )
				inventoryStmt.setNull(offset++, 91);
			else
				inventoryStmt.setDate(offset++, inventory.inventory_date);
			if ( inventory.warehouse == null )
				inventoryStmt.setNull(offset++, 4);
			else
				inventoryStmt.setInt(offset++, inventory.warehouse);
			if ( inventory.description == null )
				inventoryStmt.setNull(offset++, 12);
			else
				inventoryStmt.setString(offset++, inventory.description);
		}
		inventoryStmt.executeUpdate();
		inventoryInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Inventorys in {} milliseconds.", size, inventoryInserted, elapsed );		
	}
		
