	public static class Question {
		protected Integer id; 
		protected Integer domain; 
		protected Boolean active; 
		protected String question_text; 
		protected Short type; 
		protected String argument; 
		protected String alias; 
	}
	
	protected void insertQuestion( List<Question> questions )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = questions.size();
		if ( questionStmtSize != size ) {
			if ( questionStmt != null ) {
				questionStmt.close();
			}
			String values = "(?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			questionStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO question (id,domain,active,question_text,type,argument,alias)"  
				+" VALUES " + valuesList.toString()  );
			
			questionStmtSize = size;
		}

		int offset = 1;
			
		for (Question question : questions) {
			if ( question.id == null )
				questionStmt.setNull(offset++, 4);
			else
				questionStmt.setInt(offset++, question.id);
			if ( question.domain == null )
				questionStmt.setNull(offset++, 4);
			else
				questionStmt.setInt(offset++, question.domain);
			if ( question.active == null )
				questionStmt.setNull(offset++, -7);
			else
				questionStmt.setBoolean(offset++, question.active);
			if ( question.question_text == null )
				questionStmt.setNull(offset++, 12);
			else
				questionStmt.setString(offset++, question.question_text);
			if ( question.type == null )
				questionStmt.setNull(offset++, -6);
			else
				questionStmt.setShort(offset++, question.type);
			if ( question.argument == null )
				questionStmt.setNull(offset++, -1);
			else
				questionStmt.setString(offset++, question.argument);
			if ( question.alias == null )
				questionStmt.setNull(offset++, 12);
			else
				questionStmt.setString(offset++, question.alias);
		}
		questionStmt.executeUpdate();
		questionInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Questions in {} milliseconds.", size, questionInserted, elapsed );		
	}
		
