	private int accountStmtSize = 0;

	private int accountInserted = 0;

	private List<Account> accounts = 
		new LinkedList<Account>();

	private PreparedStatement accountStmt = null;

	public static class Account {
		protected Integer id; 
		protected Integer domain; 
		protected String code; 
		protected String description; 
		protected String alias; 
		protected Short entryEnabled; 
		protected Short level; 
	}
	
	protected void insertAccount( List<Account> accounts )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = accounts.size();
		if ( accountStmtSize != size ) {
			if ( accountStmt != null ) {
				accountStmt.close();
			}
			String values = "(?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			accountStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO account (id,domain,code,description,alias,entryEnabled,level)"  
				+" VALUES " + valuesList.toString()  );
			
			accountStmtSize = size;
		}

		int offset = 1;
			
		for (Account account : accounts) {
			if ( account.id == null )
				accountStmt.setNull(offset++, 4);
			else
				accountStmt.setInt(offset++, account.id);
			if ( account.domain == null )
				accountStmt.setNull(offset++, 4);
			else
				accountStmt.setInt(offset++, account.domain);
			if ( account.code == null )
				accountStmt.setNull(offset++, 1);
			else
				accountStmt.setString(offset++, account.code);
			if ( account.description == null )
				accountStmt.setNull(offset++, 12);
			else
				accountStmt.setString(offset++, account.description);
			if ( account.alias == null )
				accountStmt.setNull(offset++, 12);
			else
				accountStmt.setString(offset++, account.alias);
			if ( account.entryEnabled == null )
				accountStmt.setNull(offset++, -6);
			else
				accountStmt.setShort(offset++, account.entryEnabled);
			if ( account.level == null )
				accountStmt.setNull(offset++, -6);
			else
				accountStmt.setShort(offset++, account.level);
		}
		accountStmt.executeUpdate();
		accountInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Accounts in {} milliseconds.", size, accountInserted, elapsed );		
	}
		
