	protected void insertFinance( List<Finance> finances )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = finances.size();
		if ( financeStmtSize != size ) {
			if ( financeStmt != null ) {
				financeStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			financeStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO finance (id,domain,payment,registry,rdocument,rdocument_type,rdocument_country,rname,amount,expenses,concept,invoice,due_date,pay_method,bank,bank_account,status,security_level,scope,payroll,finance_group)"  
				+" VALUES " + valuesList.toString()  );
			
			financeStmtSize = size;
		}

		int offset = 1;
			
		for (Finance finance : finances) {
			if ( finance.id == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.id);
			if ( finance.domain == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.domain);
			if ( finance.payment == null )
				financeStmt.setNull(offset++, -7);
			else
				financeStmt.setBoolean(offset++, finance.payment);
			if ( finance.registry == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.registry);
			if ( finance.rdocument == null )
				financeStmt.setNull(offset++, 12);
			else
				financeStmt.setString(offset++, finance.rdocument);
			if ( finance.rdocument_type == null )
				financeStmt.setNull(offset++, -6);
			else
				financeStmt.setShort(offset++, finance.rdocument_type);
			if ( finance.rdocument_country == null )
				financeStmt.setNull(offset++, 12);
			else
				financeStmt.setString(offset++, finance.rdocument_country);
			if ( finance.rname == null )
				financeStmt.setNull(offset++, 12);
			else
				financeStmt.setString(offset++, finance.rname);
			if ( finance.amount == null )
				financeStmt.setNull(offset++, 8);
			else
				financeStmt.setDouble(offset++, finance.amount);
			if ( finance.expenses == null )
				financeStmt.setNull(offset++, 8);
			else
				financeStmt.setDouble(offset++, finance.expenses);
			if ( finance.concept == null )
				financeStmt.setNull(offset++, 12);
			else
				financeStmt.setString(offset++, finance.concept);
			if ( finance.invoice == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.invoice);
			if ( finance.due_date == null )
				financeStmt.setNull(offset++, 91);
			else
				financeStmt.setDate(offset++, finance.due_date);
			if ( finance.pay_method == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.pay_method);
			if ( finance.bank == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.bank);
			if ( finance.bank_account == null )
				financeStmt.setNull(offset++, 12);
			else
				financeStmt.setString(offset++, finance.bank_account);
			if ( finance.status == null )
				financeStmt.setNull(offset++, -6);
			else
				financeStmt.setShort(offset++, finance.status);
			if ( finance.security_level == null )
				financeStmt.setNull(offset++, -6);
			else
				financeStmt.setShort(offset++, finance.security_level);
			if ( finance.scope == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.scope);
			if ( finance.payroll == null )
				financeStmt.setNull(offset++, -7);
			else
				financeStmt.setBoolean(offset++, finance.payroll);
			if ( finance.finance_group == null )
				financeStmt.setNull(offset++, 4);
			else
				financeStmt.setInt(offset++, finance.finance_group);
		}
		financeStmt.executeUpdate();
		financeInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Finances in {} milliseconds.", size, financeInserted, elapsed );		
	}
		
