	private int invoice_attachStmtSize = 0;

	private int invoice_attachInserted = 0;

	private List<Invoice_attach> invoice_attachs = 
		new LinkedList<Invoice_attach>();

	private PreparedStatement invoice_attachStmt = null;

	public static class Invoice_attach {
		protected Integer id; 
		protected Integer domain; 
		protected Integer invoice; 
		protected Short mimeType; 
		protected String description; 
		protected Blob data; 
		protected Short type; 
		protected Date attach_date; 
	}
	
	protected void insertInvoice_attach( List<Invoice_attach> invoice_attachs )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = invoice_attachs.size();
		if ( invoice_attachStmtSize != size ) {
			if ( invoice_attachStmt != null ) {
				invoice_attachStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			invoice_attachStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO invoice_attach (id,domain,invoice,mimeType,description,data,type,attach_date)"  
				+" VALUES " + valuesList.toString()  );
			
			invoice_attachStmtSize = size;
		}

		int offset = 1;
			
		for (Invoice_attach invoice_attach : invoice_attachs) {
			if ( invoice_attach.id == null )
				invoice_attachStmt.setNull(offset++, 4);
			else
				invoice_attachStmt.setInt(offset++, invoice_attach.id);
			if ( invoice_attach.domain == null )
				invoice_attachStmt.setNull(offset++, 4);
			else
				invoice_attachStmt.setInt(offset++, invoice_attach.domain);
			if ( invoice_attach.invoice == null )
				invoice_attachStmt.setNull(offset++, 4);
			else
				invoice_attachStmt.setInt(offset++, invoice_attach.invoice);
			if ( invoice_attach.mimeType == null )
				invoice_attachStmt.setNull(offset++, -6);
			else
				invoice_attachStmt.setShort(offset++, invoice_attach.mimeType);
			if ( invoice_attach.description == null )
				invoice_attachStmt.setNull(offset++, 12);
			else
				invoice_attachStmt.setString(offset++, invoice_attach.description);
			if ( invoice_attach.data == null )
				invoice_attachStmt.setNull(offset++, -4);
			else
				invoice_attachStmt.setBlob(offset++, invoice_attach.data);
			if ( invoice_attach.type == null )
				invoice_attachStmt.setNull(offset++, -6);
			else
				invoice_attachStmt.setShort(offset++, invoice_attach.type);
			if ( invoice_attach.attach_date == null )
				invoice_attachStmt.setNull(offset++, 91);
			else
				invoice_attachStmt.setDate(offset++, invoice_attach.attach_date);
		}
		invoice_attachStmt.executeUpdate();
		invoice_attachInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Invoice_attachs in {} milliseconds.", size, invoice_attachInserted, elapsed );		
	}
		
