	protected void insertUser( List<User> users )
	throws SQLException {
		long start = System.currentTimeMillis();
		int size = users.size();
		if ( userStmtSize != size ) {
			if ( userStmt != null ) {
				userStmt.close();
			}
			String values = "(?,?,?,?,?,?,?,?,?,?)";
			StringBuffer valuesList = new StringBuffer(values);
			for ( int i = 1; i < size; i++ ) {
				valuesList.append(",");
				valuesList.append(values);
			}
	
			userStmt = 
				mysqlConnection.prepareStatement(
				"INSERT INTO user (id,domain,name,login,enterprise,registry,active,password,passwordExpiration,toolbar)"  
				+" VALUES " + valuesList.toString()  );
			
			userStmtSize = size;
		}

		int offset = 1;
			
		for (User user : users) {
			if ( user.id == null )
				userStmt.setNull(offset++, 4);
			else
				userStmt.setInt(offset++, user.id);
			if ( user.domain == null )
				userStmt.setNull(offset++, 4);
			else
				userStmt.setInt(offset++, user.domain);
			if ( user.name == null )
				userStmt.setNull(offset++, 12);
			else
				userStmt.setString(offset++, user.name);
			if ( user.login == null )
				userStmt.setNull(offset++, 12);
			else
				userStmt.setString(offset++, user.login);
			if ( user.enterprise == null )
				userStmt.setNull(offset++, 4);
			else
				userStmt.setInt(offset++, user.enterprise);
			if ( user.registry == null )
				userStmt.setNull(offset++, 4);
			else
				userStmt.setInt(offset++, user.registry);
			if ( user.active == null )
				userStmt.setNull(offset++, -7);
			else
				userStmt.setBoolean(offset++, user.active);
			if ( user.password == null )
				userStmt.setNull(offset++, 12);
			else
				userStmt.setString(offset++, user.password);
			if ( user.passwordExpiration == null )
				userStmt.setNull(offset++, 91);
			else
				userStmt.setDate(offset++, user.passwordExpiration);
			if ( user.toolbar == null )
				userStmt.setNull(offset++, -6);
			else
				userStmt.setShort(offset++, user.toolbar);
		}
		userStmt.executeUpdate();
		userInserted += size;

		// elapsed time in milliseconds
		long elapsed = System.currentTimeMillis() - start;
		info("Inserted {}/{} Users in {} milliseconds.", size, userInserted, elapsed );		
	}
		
